import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Color } = ctx.THREE;

  const root = new Group();

  // Inner lift container so hover/press motion doesn't fight adapter-set scenePosition
  const lift = new Group();
  root.add(lift);

  // Atlas ratio 512x320 -> aspect 1.6; size the card to nest within pricing hub
  const cardW = 2.4;
  const cardH = cardW * (320 / 512); // 1.5
  const cardGeo = new PlaneGeometry(cardW, cardH);
  const cardMat = new MeshBasicNodeMaterial({ color: 0xffffff, transparent: true, opacity: 1 });

  ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
    tex.colorSpace = ctx.THREE.SRGBColorSpace;
    cardMat.map = tex;
    cardMat.needsUpdate = true;
  });

  const card = new Mesh(cardGeo, cardMat);
  lift.add(card);

  // Accent focus edge — thin signal-red strip along the bottom of the panel
  const accentColor = new Color(config.intent?.visualSpec?.colors?.accent ?? '#ff2a38');
  const edgeGeo = new PlaneGeometry(cardW, 0.035);
  const edgeMat = new MeshBasicNodeMaterial({ color: accentColor, transparent: true, opacity: 0.85 });
  const edge = new Mesh(edgeGeo, edgeMat);
  edge.position.set(0, -cardH / 2 + 0.0175, 0.002);
  lift.add(edge);

  // Soft inner border to read card edge against dark stage
  const borderGeo = new PlaneGeometry(cardW + 0.02, cardH + 0.02);
  const borderMat = new MeshBasicNodeMaterial({ color: new Color('#16161d'), transparent: true, opacity: 0.0 });
  const border = new Mesh(borderGeo, borderMat);
  border.position.z = -0.002;
  lift.add(border);

  // ---- Handlers ----
  let hoverActive = false;
  const baseY = 0;
  const liftY = 0.15;

  root.userData.handlers = {};

  root.userData.handlers.onHover = (hovering) => {
    hoverActive = hovering;
    gsap.killTweensOf(lift.position);
    gsap.to(lift.position, {
      y: hovering ? baseY + liftY : baseY,
      duration: hovering ? 0.6 : 0.5,
      ease: 'power3.out'
    });
    gsap.to(edgeMat, {
      opacity: hovering ? 1.0 : 0.85,
      duration: 0.3,
      ease: 'power2.out'
    });
  };

  let pressTl = null;
  root.userData.handlers.onClick = () => {
    ctx.emit('hub-pricing.select', { source: 'hub-pricing-quote' });
    if (pressTl) pressTl.kill();
    pressTl = gsap.timeline()
      .to(lift.scale, { x: 0.97, y: 0.97, duration: 0.12, ease: 'back.out(2)' })
      .to(lift.scale, { x: 1.0, y: 1.0, duration: 0.3, ease: 'power4.out' });
  };

  // entrance — weighted-settle fallback if no entrance primitive runs
  lift.position.y = 0.4;
  lift.scale.set(1.04, 1.04, 1);
  gsap.to(lift.position, { y: baseY, duration: 0.7, ease: 'power3.out', delay: 0.05 });
  gsap.to(lift.scale, { x: 1.0, y: 1.0, z: 1.0, duration: 0.9, ease: 'power4.out', delay: 0.05 });

  // ---- Cinematic primitives ----
  const primitiveCleanups = [];
  const primitives = config.cinematicPrimitives ?? [];
  for (const p of primitives) {
    try {
      const r = ctx.primitives[p.name](lift, p.params ?? {});
      if (r && typeof r.cleanup === 'function') primitiveCleanups.push(r.cleanup);
    } catch (e) {
      // primitive optional; never crash the node
    }
  }

  // ---- Cleanup ----
  root.userData.cleanup = () => {
    gsap.killTweensOf(lift.position);
    gsap.killTweensOf(lift.scale);
    if (pressTl) pressTl.kill();
    primitiveCleanups.forEach((fn) => { try { fn(); } catch (_) {} });
    cardGeo.dispose();
    cardMat.dispose();
    edgeGeo.dispose();
    edgeMat.dispose();
    borderGeo.dispose();
    borderMat.dispose();
  };

  return root;
}
